using AwesomeAssertions;
using Oocx.TfPlan2Md.RenderTargets.GitHub;
using TUnit.Core;

namespace Oocx.TfPlan2Md.Tests.RenderTargets;

/// <summary>
/// Tests for <see cref="GitHubDiffFormatter"/> to ensure GitHub-specific diff output remains stable.
/// </summary>
public class GitHubDiffFormatterTests
{
    [Test]
    public async Task FormatDiff_WhenBothValuesAreNull_ReturnsEmpty()
    {
        var formatter = new GitHubDiffFormatter();

        var result = formatter.FormatDiff(null, null);

        result.Should().Be(string.Empty);

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatDiff_WhenValuesAreEqual_ReturnsEscapedInlineCode()
    {
        var formatter = new GitHubDiffFormatter();

        var result = formatter.FormatDiff("value*", "value*");

        result.Should().Be("<code>value\\*</code>");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatDiff_WhenValuesDiffer_UsesSimpleDiffWithEscaping()
    {
        var formatter = new GitHubDiffFormatter();

        var result = formatter.FormatDiff("a|b", "a|c");

        result.Should().Be("- `a\\|b`<br>+ `a\\|c`");

        await Task.CompletedTask;
    }
}

using AwesomeAssertions;
using Oocx.TfPlan2Md.RenderTargets.AzureDevOps;
using TUnit.Core;

namespace Oocx.TfPlan2Md.Tests.RenderTargets;

/// <summary>
/// Tests for <see cref="AzureDevOpsDiffFormatter"/> to validate inline diff rendering.
/// </summary>
public class AzureDevOpsDiffFormatterTests
{
    [Test]
    public async Task FormatDiff_WhenValuesAreNull_ReturnsEmpty()
    {
        var formatter = new AzureDevOpsDiffFormatter();

        var result = formatter.FormatDiff(null, null);

        result.Should().Be(string.Empty);

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatDiff_WhenValuesAreEqual_ReturnsEscapedInlineCode()
    {
        var formatter = new AzureDevOpsDiffFormatter();

        var result = formatter.FormatDiff("value*", "value*");

        result.Should().Be("<code>value\\*</code>");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatDiff_WhenValuesDiffer_WrapsInlineDiffContent()
    {
        var formatter = new AzureDevOpsDiffFormatter();

        var result = formatter.FormatDiff("foo", "bar");

        result.Should().StartWith("<code style=\"display:block; white-space:normal; padding:0; margin:0;\">");
        result.Should().Contain("-foo");
        result.Should().Contain("+bar");
        result.Should().Contain("<br>");
        result.Should().EndWith("</code>");

        await Task.CompletedTask;
    }
}

using AwesomeAssertions;
using Oocx.TfPlan2Md.MarkdownGeneration;
using Oocx.TfPlan2Md.Platforms.Azure;
using TUnit.Core;

namespace Oocx.TfPlan2Md.Tests.MarkdownGeneration;

/// <summary>
/// Tests for Azure scope formatting helpers to ensure template-friendly output across scope levels.
/// </summary>
public class ScribanHelpersAzureScopeFormattingTests
{
    [Test]
    public async Task FormatAzureScopeForTable_WhenResourceGroup_ReturnsGroupWithSubscription()
    {
        var scope = new ScopeInfo("rg1", "Microsoft.Resources/resourceGroups", "sub1", "rg1", ScopeLevel.ResourceGroup, "summary", "summary:", "rg1", "details");

        var result = ScribanHelpers.FormatAzureScopeForTable(scope);

        result.Should().Contain("rg1");
        result.Should().Contain("subscription");
        result.Should().Contain("sub1");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatAzureScopeForTable_WhenResourceWithResourceGroup_ReturnsResourceWithContext()
    {
        var scope = new ScopeInfo("kv1", "Microsoft.KeyVault/vaults", "sub1", "rg1", ScopeLevel.Resource, "summary", "summary:", "kv1", "details");

        var result = ScribanHelpers.FormatAzureScopeForTable(scope);

        result.Should().Contain("Microsoft.KeyVault/vaults");
        result.Should().Contain("kv1");
        result.Should().Contain("rg1");
        result.Should().Contain("sub1");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatAzureScopeForTable_WhenResourceWithoutResourceGroup_UsesSubscriptionOnly()
    {
        var scope = new ScopeInfo("vault", "Microsoft.KeyVault/vaults", "sub-only", string.Empty, ScopeLevel.Resource, "summary", "summary:", "vault", "details");

        var result = ScribanHelpers.FormatAzureScopeForTable(scope);

        result.Should().Contain("vault");
        result.Should().Contain("Microsoft.KeyVault/vaults");
        result.Should().Contain("sub-only");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatAzureScopeForTable_WhenSubscription_ReturnsSubscriptionText()
    {
        var scope = new ScopeInfo("sub-name", "subscription", "sub-123", null, ScopeLevel.Subscription, "summary", "summary:", "sub-name", "details");

        var result = ScribanHelpers.FormatAzureScopeForTable(scope);

        result.Should().Contain("subscription");
        result.Should().Contain("sub-123");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatAzureScopeForTable_WhenManagementGroup_AppendsLabel()
    {
        var scope = new ScopeInfo("mgmt", "mg", null, null, ScopeLevel.ManagementGroup, "summary", "summary:", "mgmt", "details");

        var result = ScribanHelpers.FormatAzureScopeForTable(scope);

        result.Should().Contain("mgmt");
        result.Should().Contain("Management Group");

        await Task.CompletedTask;
    }

    [Test]
    public async Task FormatAzureScopeForTable_WhenUnknownLevel_ReturnsDetails()
    {
        var scope = new ScopeInfo("name", "type", null, null, ScopeLevel.Unknown, "summary", "summary:", "name", "detail_with_special*_chars");

        var result = ScribanHelpers.FormatAzureScopeForTable(scope);

        result.Should().Be("detail_with_special\\*_chars");

        await Task.CompletedTask;
    }
}

using System.Text.Json;
using AwesomeAssertions;
using Oocx.TfPlan2Md.MarkdownGeneration;
using Scriban.Runtime;
using TUnit.Core;
using AzApiHelpers = Oocx.TfPlan2Md.MarkdownGeneration.ScribanHelpers;

namespace Oocx.TfPlan2Md.Tests.MarkdownGeneration;

/// <summary>
/// Tests for azapi metadata extraction helper to ensure template inputs remain correct after refactoring.
/// </summary>
public class AzApiMetadataExtractionTests
{
    [Test]
    public async Task ExtractAzapiMetadata_WithCompleteChange_FormatsExpectedFields()
    {
        var afterState = JsonDocument.Parse("""
            {
                "type": "Microsoft.Sql/servers@2023-01-01",
                "name": "sql-primary",
                "parent_id": "/subscriptions/sub-1/resourceGroups/rg-sql",
                "location": "westeurope",
                "tags": { "env": "prod" }
            }
            """).RootElement;

        var change = new ResourceChangeModel
        {
            Address = "azapi_resource.sql",
            Type = "azapi_resource",
            Name = "sql",
            ProviderName = "azapi",
            Action = "create",
            ActionSymbol = "+",
            AttributeChanges = Array.Empty<AttributeChangeModel>(),
            AfterJson = afterState
        };

        ScriptObject result = AzApiHelpers.ExtractAzapiMetadata(change);

        result.Should().ContainKey("type").WhoseValue.Should().Be("`Microsoft.Sql/servers@2023-01-01`");
        result.Should().ContainKey("name").WhoseValue.Should().Be("`sql-primary`");
        result.Should().ContainKey("parent_id").WhoseValue.Should().NotBeNull();
        result.Should().ContainKey("location").WhoseValue.Should().Be("🌍 `westeurope`");
        result.Should().ContainKey("tags").WhoseValue.Should().NotBeNull();

        await Task.CompletedTask;
    }

    [Test]
    public async Task ExtractAzapiMetadata_WithInvalidInput_ReturnsEmptyScriptObject()
    {
        ScriptObject result = AzApiHelpers.ExtractAzapiMetadata(new object());

        result.Keys.Should().BeEmpty();

        await Task.CompletedTask;
    }
}

